var r=[{title:`Senzații normale de antrenament`,text:`Mușchii se pot simți calzi, obosiți sau ca și cum ar arde în timpul contracțiilor repetate. Durerea musculară cu debut tardiv poate apărea la o zi sau două după o muncă necunoscută. Aceste senzații sunt de obicei diferite de o durere bruscă, ca o înjunghiere, de o articulație care pare instabilă, de simptome care se răspândesc pe un membru sau de un disconfort care rămâne sau se agravează chiar și după ce te oprești.`},{title:`Mai mult decât o singură cifră`,text:`O evaluare a durerii de la 0 la 10 poate descrie cât de puternică este durerea, dar nu poate spune cauza. O abordare de tip semafor te ajută să sortezi ce simți. Verde este efortul obișnuit cu control constant. Galben este un disconfort neobișnuit sau în creștere și înseamnă oprire sau schimbarea exercițiului. Roșu înseamnă simptome severe sau alarmante care cer o evaluare medicală.`},{title:`Ce să faci`,text:`Oprește mișcarea care o provoacă. Redu sarcina sau amplitudinea doar dacă asta ți se pare confortabil și nu tot încerca ca să dovedești că o poți tolera. O umflătură nouă, amorțeala, slăbiciunea evidentă sau simptomele după o cădere cer o privire mai atentă. Durerea are multe cauze posibile, iar o aplicație nu poate numi accidentarea ta.`},{title:`Exemplu`,text:`Senzația de arsură în coapse spre sfârșitul unei serii de urcări pe treaptă este probabil efort muscular. Un genunchi care se blochează brusc dureros sau pe care nu te poți sprijini este altceva și schimbarea numărului de repetări nu o va rezolva.`},{title:`Folosirea TrainUp`,text:`Dacă ceva doare în timpul unui antrenament, atinge „Simt durere”. Exercițiul se încheie imediat și rămâne în afara planurilor tale până îl reactivezi din Profil. După un antrenament poți raporta durerea sau disconfortul cu zona corpului și exercițiul și îți poți actualiza limitările în Profil. TrainUp nu oferă programe de recuperare. Mergi la un medic sau la un fizioterapeut pentru durerea care persistă, este severă sau te îngrijorează.`}];var i=[{label:`NHS: durerea de articulații`,url:`https://www.nhs.uk/symptoms/joint-pain/`},{label:`NHS: durerea de genunchi și când să ceri ajutor`,url:`https://www.nhs.uk/symptoms/knee-pain/`},{label:`NHS: durerea de spate și semnele urgente de avertizare`,url:`https://www.nhs.uk/conditions/back-pain/`}];var t={sections:r,sources:i};export{t as default,r as sections,i as sources};